2 · Code by Zapier › Run JavaScript (rename "Check order"): Input Data raw = [1. Raw Body]; secret = your shared token (the lesson's sample is hl-web-7Q2x; for real use a long random string). Code:
const errors = [];
let order;
try { order = JSON.parse(inputData.raw); }
catch (e) { order = {}; errors.push("body is not valid JSON"); }
if (order.token !== inputData.secret) errors.push("wrong or missing token");
if (!order.customer || !order.customer.phone) errors.push("missing phone");
if (!Array.isArray(order.items) || order.items.length === 0) errors.push("no items");
let items_total = 0;
const line_items = (order.items || []).map((it, i) => {
  const qty = Number(it.qty), unit_price = Number(it.unit_price);
  if (!(qty > 0)) errors.push(`item ${i + 1}: bad qty`);
  if (!(unit_price > 0)) errors.push(`item ${i + 1}: bad price`);
  const line_total = qty * unit_price;
  items_total += line_total;
  return { order_id: order.order_id, sku: it.sku, qty, unit_price, line_total };
});
const delivery_fee = Number(order.delivery_fee) || 0;
const total = items_total + delivery_fee;
if (order.total !== undefined && Number(order.total) !== total)
  errors.push(`total mismatch: sent ${order.total}, calculated ${total}`);
output = {
  order_id: order.order_id || "",
  phone: (order.customer || {}).phone || "",
  valid: errors.length === 0,
  errors: errors.join("; "),
  items_total, delivery_fee, total,
  item_count: line_items.length,
  line_items    // wrapped in a key, so later steps run once, not once per item
};
